H._checkEngagementAlerts = function () {
  try {
    const THIRTY_DAYS = 30 * 24 * 60 * 60 * 1000;
    const u = H.currentUser();

    if (u) {
      // A. Auto-expire listings older than 30 days
      let changed = false;
      (H.state.listings || []).forEach(function (l) {
        if (l.sellerId === u.id && l.status === 'active' && (Date.now() - l.createdAt) > THIRTY_DAYS) {
          l.status = 'expired';
          changed = true;
        }
      });
      if (changed) {
        H.saveState();
        H.toast('Some of your listings have expired. Renew them in My Listings.');
      }

      // B. Price drop alerts
      const savedPrices = H.state.savedPrices || {};
      const saves = (H.state.saves || {})[u.id] || [];
      const priceDrops = [];
      saves.forEach(function (lid) {
        const listing = (H.state.listings || []).find(function (l) { return l.id === lid; });
        if (!listing || !savedPrices[lid]) return;
        if (listing.price < savedPrices[lid]) {
          priceDrops.push({ title: listing.title, oldPrice: savedPrices[lid], newPrice: listing.price, currency: listing.currency });
          savedPrices[lid] = listing.price;
        }
      });
      if (priceDrops.length > 0) {
        H.state.savedPrices = savedPrices;
        H.saveState();
        const first = priceDrops[0];
        H.toast('Price drop: ' + first.title + ' is now ' + H.fmtPrice(first.newPrice, first.currency) + ' (was ' + H.fmtPrice(first.oldPrice, first.currency) + ')');
      }
    }
  } catch (e) {
    console.warn('_checkEngagementAlerts:', e);
  }
};

// ── Cloudflare R2 helpers ────────────────────────────────────────────────────
H.uploadToR2 = async function (blob, key, contentType) {
  var session = await window.supabase.auth.getSession();
  var token = session && session.data && session.data.session && session.data.session.access_token;
  if (!token) {
    try {
      var refreshed = await window.supabase.auth.refreshSession();
      token = refreshed && refreshed.data && refreshed.data.session && refreshed.data.session.access_token;
    } catch (_) {}
  }
  if (!token) throw new Error('Not authenticated');
  var res = await fetch(window.SUPABASE_URL + '/functions/v1/get-r2-upload-url', {
    method: 'POST',
    headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' },
    body: JSON.stringify({ key: key, contentType: contentType }),
  });
  if (!res.ok) {
    var errText = '';
    try { errText = (await res.json()).error || ''; } catch(e) {}
    throw new Error('R2 upload-url error: ' + (errText || res.status));
  }
  var payload = await res.json();
  var up = await fetch(payload.signedUrl, { method: 'PUT', headers: { 'Content-Type': contentType }, body: blob });
  if (!up.ok) throw new Error('R2 PUT failed: ' + up.status);
  return payload.publicUrl;
};

H.r2SignedGetUrl = async function (key, expiresIn) {
  if (!key) return null;
  try {
    var session = await window.supabase.auth.getSession();
    var token = session && session.data && session.data.session && session.data.session.access_token;
    if (!token) {
      try {
        var ref2 = await window.supabase.auth.refreshSession();
        token = ref2 && ref2.data && ref2.data.session && ref2.data.session.access_token;
      } catch (_) {}
    }
    if (!token) return null;
    var res = await fetch(window.SUPABASE_URL + '/functions/v1/get-r2-upload-url', {
      method: 'POST',
      headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' },
      body: JSON.stringify({ key: key, verb: 'GET', expiresIn: expiresIn || 300 }),
    });
    if (!res.ok) return null;
    var data = await res.json();
    return data.signedUrl || null;
  } catch (e) { return null; }
};

